/*字體*/
@import url("https://fontsapi.zeoseven.com/906/main/result.css");

body {
    font-family: "Swei Spring CJK SC";
    font-weight: normal;
}

:root {
    --mesTextPadding: 8%; /*聊天氣泡文字左右內距*/
    --opacity: 0.8; /*圖標透明度*/
    --chat-background-color: var(--SmartThemeChatTintColor);
    --mainFontSize: calc(var(--fontScale)* 16px); /* 主字体大小 */
    --topbarIconSize: calc(var(--mainFontSize)* 1.15); /* 顶栏图标大小 */
    --bottomFormIconSize: calc(var(--mainFontSize)* 1.25); /*底欄圖標大小*/
    --genericRadius: 0px; /* 通用圆角 */
    --warning: #ce3636;
    --crimson70a: #acacac63;
    --crimson-hover: color-mix(in srgb, var(--SmartThemeUnderlineColor), transparent 90%) !important;
    --standardIconSize: calc(var(--mainFontSize)* 1);
    --bottomFormBlockPadding: calc(var(--mainFontSize) / 1.5);
    --scrollBarWidth: 2px;
    --pagePadding: calc(var(--scrollBarWidth) + 2px);
    --genericLineHeight: calc(var(--mainFontSize)* 1.5); /* 通用行高 */

    /* ==== 所有颜色定义 ==== */
    --topbar-color: color-mix(in srgb, var(--ui-color-main) 40%, transparent); /*頂欄與底欄透明度與顏色*/
    --panel-color: color-mix(in srgb, var(--ui-color-main) 100%, transparent); /*左欄右欄透明度與顏色*/
    --ui-color-main: var(--SmartThemeBlurTintColor);
    --navBackgroundColor: var(--SmartThemeBlurTintColor);
    --utilityColor: #1B1C1E70; /* 说明文字 */
    --buttonFill: color-mix(in srgb, var(--SmartThemeBlurTintColor), white 10%); /* 按钮背景颜色 */
    --menuBackgroundColor: var(--navBackgroundColor); /* 菜单背景颜色 */
    --accentColor: var(--SmartThemeUnderlineColor); /* 装饰色1 思维链，文字装饰，段落装饰等 */
    --accentColorOverlay: color-mix(in srgb, var(--SmartThemeBorderColor), transparent 95%); /* 装饰色2 */
    --scrollBarColor: var(--SmartThemeUnderlineColor); /* 滚动条颜色 */
    --boxShadowSubtle: 1px 1px 0px var(--SmartThemeBorderColor); /* 阴影颜色 */
    --boxShadowSubtleAlt: 1px 1px 0px var(--SmartThemeUnderlineColor); /* 阴影颜色 */
  } 

/*🎀 聊天氣泡頂部元素*/
/* 頭像大小 */
.mes .avatar img {
    height: 110px !important;
    width: 90px !important;
    border-radius: 0% !important; 
    box-shadow: none !important;
    }

/*🍺頭像位置*/
.mesAvatarWrapper {
    top: -108px !important;
    left: calc(50% - 167px);
    object-fit: cover !important;
    z-index: 5;
    position: absolute;
}

.mes_edit_buttons, .mes_buttons, .mes_ghost, .mes .name_text, .mesIDDisplay, .mes_timer,
.tokenCounterDisplay,.icon-svg,.timestamp {
  color: #6c340f;
  position: absolute !important;
  z-index: 5  !important;
}

/* ======================================= */
/* 🐰动图模块🐰  */
/* ======================================= */
.mes[is_user="false"] .avatar {
    position: relative !important; 
}

/* 动图覆盖层：只贴在char的头像上，绝对放过你的头像 */
.mes[is_user="false"] .avatar::after {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    height: 110px !important;
    width: 90px !important;

    /* 🐰请在这里更换爱的gif图🐰 */
    background-image: url('这里要动图链接');

    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;

    pointer-events: none; 
    border-radius: 0% !important; 
    z-index: 10; 
      /* 👇 歪头魔法：和你的聊天界面保持一致的 -2度倾斜 */
    transform: rotate(-2deg) !important; 

}

/* 🍺角色名字🐰 */
/* 🍺角色名字 -向上换行 */
.mes .name_text {
    bottom: calc(100% + 90px); /* 🎮 上下方向盘：数值越大名字越往上走 */
    left: calc(50% - -70px);    /* 左右方向盘保持你的原样 */
/* 👇 换行魔法：限制最宽能多宽，超了就给我换行 */
    max-width: 100px !important; /* 🎮 宽度方向盘：根据你的需求调整，比如设为100px，名字达到这个宽度就会折返到上一行 */
    word-break: break-all !important; /* 强制不管什么语言，到边缘就切断换行 */
    text-align: left !important; /* 可以根据喜好改成 center 居中对齐 */

    color: var(--SmartThemeQuoteColor);
    font-size: 20px;
    line-height: 1.2 !important; /* 控制一下换行后两行字之间的间距，避免太挤或太散 */
}

/* 🍺訊息編號 */
.mesIDDisplay {
    top: -57px;
    left: calc(50% + 250px);
    font-size: 16px !important;
}

/* 🍺日期时间 */
.timestamp {
    top: -160px;
    left: calc(50% - 122px);
    font-size: 10px !important;
}

/* 🍺Token */
.tokenCounterDisplay { 
    top: 52px;
    left: 270px;
    font-size: 12px !important;
}

/* 🍺计 时 */
.mes_timer {
    top: 40px ;
    left: 270px;
    font-size: 12px !important;
}

/* 🍺模型圖標 */
.icon-svg {
    top: -85px;
    left: calc(50% - -100px);
    opacity: 0.6;
}

/* 🍺隱藏訊息小幽靈圖標 */
.mes_ghost {
    top: -132px; 
    left: calc(50% + 154px);
}

/* 🍺小鉛筆 */
.mes_buttons {
    top: 18px !important;
    right: 10px;
}

/* 🍺正文edit按键 */
.mes_edit_buttons {
    filter: drop-shadow(0px 0px 2px var(--buttonFill));
    top: 8px !important;
    right: 12px;
}

/* 小鉛筆顏色與透明度 */
  .mes_buttons i, 
  .mes_button i,
  .mes_edit_buttons i,
  .mes_reasoning_actions .edit_button i,
  .mes_buttons .fa-solid,
  .mes_edit_buttons .fa-solid {
    color: var(--SmartThemeUnderlineColor) !important;
    opacity: var(--opacity) !important; 
}

/* 🎀聊天氣泡裝飾*/
.mes .avatar img, .timestamp, .mesIDDisplay, .mes_timer, .tokenCounterDisplay,.icon-svg,.mes .name_text,  .mes_edit_buttons {
  transform:rotate(-2deg);
}

.mes_buttons{
  transform:rotate(-3deg);
}

/* 氣泡 頂部裝飾 */
.mes::before {
  content: "";
  position: absolute;
  width: 100%;
  height: 230px; /* 更改裝飾圖片大小。要更動聊天氣泡間隔搜body.bubblechat，更改margin-top的值 */
  background-repeat: no-repeat; 
  background-size: contain; 
  align-items: center !important; 
  background-position: center; 
  top: -180px;
  z-index: 2;
  left: calc(50% - 2px) !important;
  transform: translateX(-50%) rotate(-2deg);
}

/* Char氣泡頂部裝飾圖片 */
.mes[is_user="false"]::before {
  background-image: url('https://iili.io/qwXditj.png'); 
}

/* ========================================= */
/* 🍰 专属透明悬浮小蛋糕图层（如果不需要删除这一部分） 🐰 */
/* ========================================= */
.mes[is_user="false"] .mes_block::before {
    content: "";
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;

    /* 核心：绝对定位，让它乖乖跟着气泡一起滚动 */
    position: absolute !important;
    pointer-events: none !important;
    z-index: 10 !important; 

    /* 大小与位置 */
    width: 60px !important;  
    height: 60px !important; 
    top: -30px !important;  
    left: 50% !important;    
    transform: translateX(-50%) rotate(0deg) !important; 
}

/* ========================================= */
/* 🍰 进阶逻辑：自动发牌循环系统🐰 */
/* ========================================= */


/* 第 1, 11, 21... 个出现的 Char 气泡 */
.mes:nth-child(10n+1 of [is_user="false"]) .mes_block::before {
    background-image: url('https://files.catbox.moe/7qlfhn.png');
}

/* 第 2, 12, 22... 个出现的 Char 气泡 */
.mes:nth-child(10n+2 of [is_user="false"]) .mes_block::before {
    background-image: url('https://files.catbox.moe/53exds.png');
}

/* 第 3, 13, 23... 个 */
.mes:nth-child(10n+3 of [is_user="false"]) .mes_block::before {
    background-image: url('https://files.catbox.moe/3esje5.png');
}

/* 第 4, 14, 24... 个 */
.mes:nth-child(10n+4 of [is_user="false"]) .mes_block::before {
    background-image: url('https://files.catbox.moe/obgrsi.png');
}

/* 第 5, 15, 25... 个 */
.mes:nth-child(10n+5 of [is_user="false"]) .mes_block::before {
    background-image: url('https://files.catbox.moe/uqcwfu.png');
}

/* 第 6, 16, 26... 个 */
.mes:nth-child(10n+6 of [is_user="false"]) .mes_block::before {
    background-image: url('https://files.catbox.moe/4hqvo8.png');
}

/* 第 7, 17, 27... 个 */
.mes:nth-child(10n+7 of [is_user="false"]) .mes_block::before {
    background-image: url('https://files.catbox.moe/p2eu5y.png');
}

/* 第 8, 18, 28... 个 */
.mes:nth-child(10n+8 of [is_user="false"]) .mes_block::before {
    background-image: url('https://files.catbox.moe/kckfce.png');
}

/* 第 9, 19, 29... 个 */
.mes:nth-child(10n+9 of [is_user="false"]) .mes_block::before {
    background-image: url('https://files.catbox.moe/av079v.png');
}

/* 第 10, 20, 30... 个 (尾数为0) */
.mes:nth-child(10n of [is_user="false"]) .mes_block::before {
    background-image: url('https://files.catbox.moe/pyfy5n.png');
}

/* ========================================= */
/* 🍰 专属透明悬浮小蛋糕图层（如果不需要删除这一部分，替换成帖子里的代码） 🐰 */
/* ========================================= */


/* User气泡頂部裝飾🐰*/
.mes[is_user="true"]::before {
  background-image: url('https://iili.io/qwXdLox.png'); 
}

/* 疊加紙張紋理 */
.mes::after {
    content: '';
    position: absolute;
    background-image: url('https://www.transparenttextures.com/patterns/black-paper.png');
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    filter: opacity(20%) grayscale(50%) contrast(1);
    pointer-events: none;
    border-radius: inherit; 
    z-index: -1;
}

/* 聊天氣泡底端文字🐰 */
.mes_block::after {
    content: " ✦⊹—	𝓢𝓹𝓻𝓲𝓷𝓴𝓵𝓮 𝓳𝓸𝔂 𝓸𝓷 𝔂𝓸𝓾𝓻 𝔀𝓸𝓻𝓭𝓼 —⊹✦";
    display: block;
    text-align: center;
    font-size: 0.9rem;
    color: var(--SmartThemeBorderColor);
    margin-top: 20px;      
    margin-bottom: 20px;      
    opacity: 0.6;
}

/* 🎀正文 */
/* 聊天气泡 */
  body.bubblechat .mes {
    border-radius: var(--genericRadius);
    margin-top: 200px; /* 聊天氣泡間隔 */
    display: flex;
    flex-direction: column;
    z-index: 0;
    padding: 50px var(--mesTextPadding) 0px var(--mesTextPadding);
  }

  .mes_text {
    line-height: var(--genericLineHeight);
    text-align: justify;
    z-index: 5 !important;
    padding: 0px;
  }

/*段距*/
.mes_text p {
    margin-bottom: 1.8em; 
  }

/*字距*/
.mes_text, .mes_text p {
    letter-spacing: 1px; 
}

 /* 對白樣式 */
.mes_text q {
  color: var(--SmartThemeQuoteColor); 
  background: linear-gradient(135deg, rgba(154, 116, 193, 0.08), rgba(154, 116, 193, 0.05));
  border-left: 3px double rgba(154, 116, 193, 0.5);
  margin: 0px 6px 0px 3px;
  padding: 0px 0px;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.0);
  position: relative;
}

/* 引用塊 */
.mes_text blockquote {
  background: color-mix(in srgb, var(--SmartThemeUnderlineColor) 10%, transparent);
  border-left: 3px double var(--SmartThemeUnderlineColor);
  padding: 16px 24px;    
  border-radius: var(--genericRadius);
  margin-bottom: 15px;
}

  .last_mes .mesAvatarWrapper {
    padding-bottom: 5px !important;
  }

  .mes_block {
    padding-left: 0px !important;
  }

  /* extension */
  .extensions_info .extension_disabled {
    color: var(--SmartThemeEmColor);
  }

/* === 圖標 ===*/
/* 🎀切換消息🐰 */
.swipeRightBlock,
.swipe_left {  
  left: 22px !important;
  color: var(--SmartThemeUnderlineColor);
}

.swipe_left {
  bottom: 12px;
}

.swipe_left::before {
  content: '🍴';
  display: inline-block;
  transform: scaleX(-1);
  opacity: var(--opacity);
}

.swipe_right::before {
  content: '🍴';
  opacity: var(--opacity);
}

  /* 🎀底欄&頂欄top bar共通樣式 */
  #top-bar, #send_form, body.no-blur #top-bar, body.no-blur #send_form {
    background-color: var(--topbar-color) !important;
    padding: 0px 8px;
    border: 0px solid var(--SmartThemeBorderColor);
  }

  #top-bar {
    border-bottom: 1px solid var(--SmartThemeBorderColor) !important;
  }

  #send_form, body.no-blur #send_form {
    border-radius: var(--genericRadius);
    border-top: 1px solid var(--SmartThemeBorderColor);
  }

  /* 按鈕 Icon Sizes & Colors */
  .fa, .fa-brands, .fa-classic, .fa-regular, .fa-sharp, .fa-solid, .fab, .far, .fas {
    font-size: var(--standardIconSize);
    color: var(--SmartThemeUnderlineColor);
  } 

/* 🎀頂欄圖標 */
/*頂欄圖標內縮*/
#top-settings-holder {
    padding: 5px !important;
}

.fa-solid:not(#load-spinner) {
  opacity: var(--opacity);
}

#persona-management-button .drawer-icon::before,
#leftNavDrawerIcon::before,
#advanced-formatting-button .drawer-icon::before, 
#user-settings-button .drawer-icon::before,
#extensions-settings-button .drawer-icon::before { 
  content: "❖";
  color: var(--SmartThemeUnderlineColor);
  font-size: var(--topbarIconSize);
}

#rightNavDrawerIcon::before,
#table_database_settings_drawer .drawer-icon::before,
#API-status-top:not(.redOverlayGlow)::before,
#WI-SP-button .drawer-icon::before,
#logo_block .drawer-icon::before,
#backgrounds-drawer-toggle .drawer-icon::before {
  content: "⟡";
  color: var(--SmartThemeUnderlineColor);
  font-size: var(--topbarIconSize);
}

/* 🍓🍧 顶栏图标交互 - 进阶状态转换版（基于77的严厉指责） */

/* 确保顶栏图标完全不透明，不受全局遮罩影响 */
#top-settings-holder .drawer-icon {
    opacity: 1 !important;
}

/* 基础平滑过渡设置：让颜色和旋转动作丝滑柔和 */
#top-settings-holder .drawer-icon::before {
    vertical-align: middle;
    transition: transform 0.3s ease-in-out, color 0.2s ease-in-out;
    display: inline-block;
}

/* 🧊 状态二：鼠标悬停（Hover） -> 加一层 #b8c9e7 渐变，稍微放大并歪一下头 */
#top-settings-holder .drawer-icon:hover::before {
    transform: scale(1.2) rotate(15deg) !important;
    background: linear-gradient(135deg, #C38380, #b8c9e7) !important; /* 粉色到冰川蓝的渐变 */
    -webkit-background-clip: text !important;
    -webkit-text-fill-color: transparent !important;
    transition: transform 0.2s ease-in-out;
}

/* 🧊 状态三：导航展开（点开） -> 纯色 #b8c9e7，翻转180度 */
#top-settings-holder .drawer-icon.openIcon::before {
    transform: rotate(180deg) !important;
    background: transparent !important; /* 洗掉悬停时的渐变背景 */
    -webkit-text-fill-color: currentcolor !important; /* 恢复原生文字颜色填充机制 */
    color: #b8c9e7 !important; /* 锁定冰川蓝 */
}

/* 🎀底欄(by Nakari)  */

#send_form .fa-solid {
  font-size: var(--bottomFormIconSize); /*底欄圖標大小*/
  opacity: var(--opacity) !important;
  color: var(--SmartThemeUnderlineColor); /*底欄顏色*/
}

#send_form textarea {
  border: none !important;
}

/* 菜单🐰 */
#options_button::before {
    content: "🎂";
}

/* 扩展 - 奶酪图标定制版 🐰*/
#extensionsMenuButton::before {
    /* 这是 cheese 图标对应的代码 */
    content: "\f7ef"; 
    /* 强制指定使用 Font Awesome 字体 */
    font-family: "Font Awesome 5 Free", "Font Awesome 6 Free", "Font Awesome 5 Solid", "Font Awesome 6 Solid" !important;
    font-weight: 900;
    /* 如果觉得奶酪太小，可以取消下面这一行的注释来调整大小 */
    /* font-size: calc(var(--icon-size) * 1.1); */
}

/* 发送消息 - 冰淇淋图标定制版 🐰*/
#send_but::before {
    /* 这是 ice-cream 图标对应的代码 */
    content: "\f810"; 
    /* 强制指定使用 Font Awesome 字体，否则图标显示不出来 */
    font-family: "Font Awesome 5 Free", "Font Awesome 6 Free", "Font Awesome 5 Solid", "Font Awesome 6 Solid" !important;
    font-weight: 900;
    transform: scaleX(1); /* 冰淇淋图标一般不需要水平翻转，如果需要翻转请改为 -1 */
}

/* 底栏输入框文案隐藏 */
#send_textarea::placeholder {
    opacity: 0;
}

/* 输入框文案 🐰*/
#nonQRFormItems::before {
    content: "✦ 𝓣𝔂𝓹𝓮 𝓼𝓸𝓶𝓮𝓽𝓱𝓲𝓷𝓰 𝓼𝔀𝓮𝓮𝓽 ✦";
    position: absolute;
    left: calc(50%);
    top: 40%;
    transform: translate(-50%, -50%);
    font-size: calc(var(--mainFontSize));
    color: color-mix(in srgb, var(--SmartThemeQuoteColor) 40%, transparent);
    pointer-events: none;
    z-index: 1;
    padding: 8px 0;
}

/*打字時輸入框透明度*/
#send_textarea:focus {
        background-color: var(--ui-color-main) !important;
        background: var(--ui-color-main) !important;
}

/* 🎀输入框换行(來自Nakari)*/
@media (max-width: 768px) {
    #nonQRFormItems {
        display: grid;
        grid-template-columns: auto 1fr auto;
        grid-template-rows: auto auto;
        place-items: center;
        padding: 0 10px 8px 10px !important; /*底欄圖標內縮*/
    }

    #leftSendForm {
        grid-row: 1 / 2;
        grid-column: 1 / 2;
    }

    #rightSendForm {
        grid-row: 1 / 2;
        grid-column: 3 / 4;
    }

    #send_textarea:focus {
        grid-row: 2 / 3;
        grid-column: 1 / 4;
        justify-self: center;
        width: 97%; /* 输入框宽度 */
        margin: 0px 0px -5px; /* 上、左右、下方间距 */
    }
}

/* 🎀extensionTopBar */
#extensionTopBar, #extensionConnectionProfiles {
  border-radius: 0px !important;
  background-color: var(--topbar-color) !important;
  border: none !important;
}

#extensionTopBar .right_menu_button {
  opacity: calc(var(--opacity) - 0.1) !important;
  color: var(--SmartThemeUnderlineColor) !important;
}

#extensionTopBarChatName, #extensionTopBarSearchInput {
  border: none !important;
  box-shadow: none !important;
  background: none !important;
}

/* 🐰首页美化感谢【yaokoulizi】老师分享🐰*/
/* 🍓🍧 首页/空闲状态 - 替换默认助手名称 */
/* 1. 重置该气泡的名字外框坐标，拉回背景图附近 */
div.mes[mesid="0"][ch_name="Assistant"][type="assistant_message"] .name_text {
    color: transparent !important; 
    position: absolute !important;

    /* 🎮 【方向盘在这里！】通过改这两个数值，把名字“开”到背景图上 */
    top: -135px !important;  /* 👈 上下移动：数值变小（比如 -80px）往上走，变大（比如 20px）往下走 */
    left:73% !important;   /* 👈 左右移动：50% 是相对气泡居中。如果偏了，可以改成具体数值比如 100px */
    transform: translateX(-50%) !important; /* 配合 left:50% 实现绝对居中 */

    display: block !important;
    width: 100% !important;
    text-align: center !important;
}

/* 2. 覆盖你的专属名字 */
div.mes[mesid="0"][ch_name="Assistant"][type="assistant_message"] .name_text::after {
    content: "准备营业" !important;  /* 👈 填要的字 */
    color: #9C7164 !important; /* 👈 可换颜色 */

    /* 👇 解除全屏锁定，跟着上面的“方向盘”走 */
    position: relative !important; 

    /* 👇 保持不换行，字号调回正常大小 */
    white-space: nowrap !important;
    font-size: 22px !important; /* 字号大小可以在这改 */
    font-weight: bold !important;
    z-index: 10 !important;
}

/* 🍓🍧 首页/空闲状态 - 替换默认助手开场白 */

/* 1. 撑起文字容器的框架 */
div.mes[mesid="0"][ch_name="Assistant"][type="assistant_message"] .mes_text {
    position: relative !important;
    min-height: 80px !important;
    padding: 10px 15px !important;
}

/* 2. 隐藏自带的默认冰冷文案 */
div.mes[mesid="0"][ch_name="Assistant"][type="assistant_message"] .mes_text > * {
    opacity: 0 !important;
    visibility: hidden !important;
    height: 0 !important;
    margin: 0 !important;
    padding: 0 !important;
